import { expect, test, type Page } from "@playwright/test";
import { setAspetto } from "../fixtures/tema";

// #634, CA-26: reference screenshots at night of the gallery and of the
// sign-in page, at 390 and 1280 px (the two projects). The theme is turned on
// with the attribute and, in a second test, with the system preference only:
// the two must give the same screenshot (same reference file).
// The references (*-scuro.png) are generated by the visual tester.

test.use({
  locale: "it-IT",
  timezoneId: "Europe/Rome",
  reducedMotion: "reduce",
});

const FIXED_NOW = new Date("2026-10-20T15:00:00+02:00");

async function settle(page: Page) {
  await page.evaluate(() => document.fonts.ready);
  // Take the pointer and the focus ring out of the picture.
  await page.mouse.move(0, 0);
}

for (const mode of ["attributo", "sistema"] as const) {
  test.describe(`tema scuro (${mode})`, () => {
    test.beforeEach(async ({ page }) => {
      await page.clock.install({ time: FIXED_NOW });
      if (mode === "sistema") await page.emulateMedia({ colorScheme: "dark" });
    });

    test("galleria intera al buio", async ({ page }) => {
      await page.goto("/design-system");
      await expect(page.locator("h1")).toHaveText("Design system");
      if (mode === "attributo") await setAspetto(page, "scuro");
      await settle(page);
      await expect(page).toHaveScreenshot("galleria-scuro.png", {
        fullPage: true,
      });
    });

    test("accesso al buio", async ({ page }) => {
      await page.goto("/accesso");
      await expect(page.locator("h1:visible")).toHaveCount(1);
      if (mode === "attributo") await setAspetto(page, "scuro");
      await settle(page);
      await expect(page).toHaveScreenshot("accesso-scuro.png", {
        fullPage: true,
      });
    });
  });
}
